import (
	"math/big"
	"math/bits"
	"testing"
)

func TestCountBits(t *testing.T) {
	var tests = []struct {
		n *big.Int
		expected int
	}{
		{
			n: &big.Int{Val: []byte{1, 0, 1, 0, 1, 0, 1, 0}},
			expected: 4,
		},
		{
			n: &big.Int{Val: []byte{0, 1, 0, 1, 0, 1, 0, 1}},
			expected: 4,
		},
		{
			n: &big.Int{Val: []byte{1, 1, 1, 1, 1, 1, 1, 1}},
			expected: 8,
		},
		{
			n: &big.Int{Val: []byte{0, 0, 0, 0, 0, 0, 0, 0}},
			expected: 0,
		},
	}

	for _, test := range tests {
		count := countBits(test.n)
		if count != test.expected {
			t.Errorf("Expected %d bits, got %d for %v", test.expected, count, test.n)
		}
	}
}

