)

func TestCountBits(t *testing.T) {
	var tests = []struct {
		n *big.Int
		expected int
	}{
		{
			n: &big.Int{SetUint64(0x8020102)}, // 0b10000000000000000000000000100010
			expected: 4,
		},
		{
			n: &big.Int{SetUint64(0x8020103)}, // 0b10000000000000000000000000100011
			expected: 4,
		},
